// All ingress events and releases share one journal. Nothing here injects a
// physics state. Browser events and fixed-step accepted inputs remain distinct.
function immutableSnapshot(value){const result=structuredClone(value);const freeze=x=>{if(x&&typeof x==='object'&&!Object.isFrozen(x)){for(const v of Object.values(x))freeze(v);Object.freeze(x);}return x;};return freeze(result);}
export class InputSession{
  constructor({keys=new Set(),onRelease=()=>{},onEvent=()=>{},capacity=2400}={}){this.keys=keys;this.onRelease=onRelease;this.onEvent=onEvent;this.capacity=capacity;this.events=[];this.serial=0;this.dropped=0;this.lastStepInput='';this.traceUntil=0;this.traceUntilSim=null;this.traceNextSeconds=null;this.latestSimTime=null;this.lastActionReceipt=null;}
  note(type,detail={}){if(type==='keydown'&&detail.accepted&&['KeyX','KeyG','KeyE','KeyQ','Digit1','Digit2','Numpad1','Numpad2'].includes(detail.code))this.armTrace();const event=immutableSnapshot({sequence:++this.serial,wallTimeMs:typeof performance!=='undefined'?performance.now():0,type,...detail,pressed:[...this.keys].sort()});this.events.push(event);if(this.events.length>this.capacity){this.events.shift();this.dropped++;}if(type!=='physics-input')this.onEvent(event);return event;}
  get tracing(){return this.traceNextSeconds!==null||(typeof performance!=='undefined'?performance.now():0)<this.traceUntil||this.traceUntilSim!==null&&this.latestSimTime!==null&&this.latestSimTime<this.traceUntilSim-1e-9;}
  armTrace(seconds=20){const duration=Math.min(20,Math.max(1,seconds));this.traceUntil=performance.now()+duration*1000;this.traceNextSeconds=duration;}
  down(event,accepted=true,reason='pilot'){if(accepted){this.keys.add(event.code);if(['KeyE','KeyQ','Digit1','Digit2','Numpad1','Numpad2'].includes(event.code))this.armTrace();}return this.note('keydown',{code:event.code,repeat:!!event.repeat,accepted,reason});}
  up(event){this.keys.delete(event.code);return this.note('keyup',{code:event.code,repeat:!!event.repeat});}
  release(reason,{pause=false}={}){const released=[...this.keys].sort();this.keys.clear();this.note('input-release',{reason,released,pause});if(['scenario-reset','context-switch'].includes(reason)){this.traceUntil=0;this.traceUntilSim=null;this.traceNextSeconds=null;this.latestSimTime=null;}this.onRelease(reason,{pause});}
  action(name,{accepted=false,state=accepted?'accepted':'rejected',reason='',telemetry=null,...details}={}){if(accepted)this.armTrace();this.lastActionReceipt=this.note('action-receipt',{name,accepted,state,reason,...details,simTime:telemetry?.simTime??null,mode:telemetry?.mode??null,maneuverFeedback:telemetry?.maneuverFeedback??null});return this.lastActionReceipt;}
  step(t,input){if(this.latestSimTime!==null&&t.simTime<this.latestSimTime){this.traceUntilSim=null;if(this.tracing)this.traceNextSeconds=20;}if(this.traceNextSeconds!==null){this.traceUntilSim=t.simTime+this.traceNextSeconds;this.traceNextSeconds=null;}this.latestSimTime=t.simTime;this.note('physics-input',{step:t.physicalStep??Math.round(t.simTime*120),simTime:t.simTime,input:{...input},mode:t.mode,stabilization:t.stabilizationMode,pilotIntent:t.pilotIntent??null,
    actual:{position:t.position?{...t.position}:null,velocity:t.velocity?{...t.velocity}:null,quaternion:t.quaternion?{...t.quaternion}:null,angularVelocity:t.angularVelocity?{...t.angularVelocity}:null,pitchDeg:t.pitchDeg??null,rollDeg:t.rollDeg??null,headingDeg:t.headingDeg??null,wheelContactCount:t.contactCount??null,rigidContactCount:t.rigidContactCount??null,attitudeTravel:t.attitudeTravel??null},
    integration:t.integration??null,controlAuthority:t.controlAuthority??null,levelRecovery:t.levelRecovery??null,maneuverFeedback:t.maneuverFeedback??null,pressureBar:t.pressureBar??null,supplyMode:t.supplyMode??null,status:t.status??null,reference:t.reference,desiredWrench:t.desiredWrench,achievedWrench:t.achievedWrench});}
  export(identity={},{clone=true}={}){return{schema:'roadster-input-session',version:2,identity,source:'received-browser-events-and-actual-fixed-step-inputs',capacity:this.capacity,physicsTracePolicy:`Production input samples at 120 Hz. After X/G/E/Q/1/2, trace until both 20 s wall time and 20 s simulation time have elapsed. The ${this.capacity}-event rolling capacity still applies and discarded events are counted. Actual poses, body-axis travel, authority and action receipts are distinct from controller references.`,droppedEvents:this.dropped,lastActionReceipt:clone&&this.lastActionReceipt?structuredClone(this.lastActionReceipt):this.lastActionReceipt,events:clone?structuredClone(this.events):this.events.slice()};}
}
